/**
 * KeyedRowBranchCall fixture. The source is the fixture-only root
 * (`fixtures/components/KeyedRowBranchCall.tsx`).
 *
 * A keyed, signal-backed `.map()` row whose conditional branch is one bare
 * expression calling a module function (#3894). `insert()` leaves a branch
 * alone while its condition is unchanged, so a row reused with a new item
 * shows the new value only through the branch's own text effect. A branch
 * with a call used to get none and kept the value the row was built with.
 *
 * Snapshots in `__snapshots__/keyed-row-branch-call.{html,client.js}` are
 * regenerated by
 * `bun run packages/adapter-tests/scripts/snapshot.ts keyed-row-branch-call`.
 */

import { defineSharedFixture, type SharedFixtureSpec } from './_helpers'
import type { InteractionStep } from '../src/types'

const LISTS = [
  'plain',
  'tern-call',
  'tern-nocall',
  'tern-template',
  'tern-declaration',
  'logical-and',
  'nested',
  'memo-destructured',
  'signal-in-call',
] as const
type List = (typeof LISTS)[number]

/** Assert the text of each of the three rows of one list. */
function rowsOf(list: List, texts: readonly [string, string, string]): InteractionStep[] {
  return texts.map((text, i) => ({
    type: 'expectText' as const,
    selector: `ol.${list} li:nth-child(${i + 1})`,
    text,
  }))
}

export const spec: SharedFixtureSpec = {
  id: 'keyed-row-branch-call',
  componentName: 'KeyedRowBranchCall',
  sourceRoot: 'fixture',
  description:
    'keyed .map() row: a conditional branch that calls a function is re-rendered when the row is reused',
  // The fixture pins the client re-render of a branch that hydration adopted
  // from the server HTML, so it has to call the helper on the server too.
  escapeNotOwed: {
    reason:
      "By design: this fixture pins the client-side re-render of a loop-row branch that hydration adopted from the server HTML. A '/* @client */' twin renders those branches on the client only, so nothing is adopted and the twin would pin a client-only mount instead. The module-scope helper refusal that DSL adapters raise here has its own fixtures (module-const-arrow-helper, module-function-helper-chain).",
  },
  interactions: [
    // Server HTML, adopted by hydration.
    ...rowsOf('plain', ['0s', '0.5s', '2s']),
    ...rowsOf('tern-call', ['0s', '0.5s', '2s']),
    ...rowsOf('tern-nocall', ['0s', '+500', '+2000']),
    ...rowsOf('tern-template', ['0s', '+0.5s', '+2s']),
    ...rowsOf('tern-declaration', ['0s', '0.5s', '2s']),
    ...rowsOf('logical-and', ['', '0.5s', '2s']),
    ...rowsOf('nested', ['0s', '0.5s', '2s']),
    ...rowsOf('memo-destructured', ['0s', '0.501s', '2.002s']),
    ...rowsOf('signal-in-call', ['0s', '0.5s', '2s']),

    // Same keys, new items: rows 2 and 3 are reused inside the arm with
    // the call, and row 1 moves into it.
    { type: 'click', selector: 'button.slower' },
    ...rowsOf('plain', ['0.25s', '1.75s', '6.25s']),
    ...rowsOf('tern-call', ['0.25s', '1.75s', '6.25s']),
    ...rowsOf('tern-nocall', ['+250', '+1750', '+6250']),
    ...rowsOf('tern-template', ['+0.25s', '+1.75s', '+6.25s']),
    ...rowsOf('tern-declaration', ['0.25s', '1.75s', '6.25s']),
    ...rowsOf('logical-and', ['0.25s', '1.75s', '6.25s']),
    ...rowsOf('nested', ['0.25s', '1.75s', '6.25s']),
    ...rowsOf('memo-destructured', ['0.25s', '1.751s', '6.252s']),
    ...rowsOf('signal-in-call', ['0.25s', '1.75s', '6.25s']),

    // A second reuse; row 3 of the nested list leaves the arm with the call.
    { type: 'click', selector: 'button.slower' },
    ...rowsOf('tern-call', ['1s', '5.5s', '19s']),
    ...rowsOf('tern-template', ['+1s', '+5.5s', '+19s']),
    ...rowsOf('tern-declaration', ['1s', '5.5s', '19s']),
    ...rowsOf('logical-and', ['1s', '5.5s', '19s']),
    ...rowsOf('nested', ['1s', '5.5s', 'long']),
    ...rowsOf('memo-destructured', ['1s', '5.501s', '19.002s']),

    // A signal read inside the call, with the rows unchanged.
    { type: 'click', selector: 'button.scale' },
    ...rowsOf('signal-in-call', ['2s', '11s', '38s']),
    ...rowsOf('tern-call', ['1s', '5.5s', '19s']),
  ],
}

export const fixture = defineSharedFixture(spec)
